xhtml:body.xhtml:script:
//
  (function() {
    function size() {
      var w = window.innerWidth, h = window.innerHeight;
      var svg = document.querySelector('svg');
      var fo  = document.querySelector('foreignObject');
      if (svg) { svg.setAttribute('width', w); svg.setAttribute('height', h); svg.setAttribute('viewBox','0 0 '+w+' '+h); }
      if (fo)  { fo.setAttribute('width', w);  fo.setAttribute('height', h); }
    }
    size();
    window.addEventListener('resize', size);

    var rootCdn = 'https://cdn.jsdelivr.net/gh/deezlightlysaltednuts-bot/petezah-mirrors@v2.4.1/';

    function renderHtml(html, base) {
      var frame = document.getElementById('fm');
      if (!frame) return;
      var fdoc = frame.contentDocument || frame.contentWindow.document;
      var baseTag = '<base href="' + (base || rootCdn) + '">';
      if (html.includes('<head>')) {
        html = html.replace('<head>', '<head>' + baseTag);
      } else {
        html = baseTag + html;
      }
      fdoc.open();
      fdoc.write(html);
      fdoc.close();
    }

    var embeddedB64 = "";
    if (embeddedB64) {
      try {
        var decoded = decodeURIComponent(escape(atob(embeddedB64)));
        renderHtml(decoded, rootCdn);
      } catch(e) {
        try { renderHtml(atob(embeddedB64), rootCdn); } catch(err) {}
      }
    }
  })();
//
